slots.VIEW:
SIM = {
  duration: 41,
  bodies: [
    { id: "ambulance", at: function (s) { const b = s.ambulance; return [b.x, b.y]; } }
  ],
  phases: [{ t0: 0, t1: 10 }, { t0: 10, t1: 41 }],
};

slots.stateAt:
// 由 analysis 运动表生成；不要手改
const state = {};
let tt0 = t;
if (tt0 < 0) tt0 = 0;
if (tt0 > 41) tt0 = 41;
let x0, y0;
if (tt0 <= 10) { x0 = 0 + 0*(tt0 - 0) + 0.5*2*(tt0 - 0)**2; y0 = 0.05; }
else if (tt0 <= 41) { x0 = 100 + 20*(tt0 - 10); y0 = 0.05; }
else { x0 = 100 + 20*(tt0 - 10); y0 = 0.05; }
state.ambulance = { x: x0, y: y0, type: "block" };
return state;

slots.drawFrame:
const amb = state.ambulance;

// 水平直路与出发点
Draw.ground(-80, 820, 0);

// 出发处的人（听者），立于出发点 x = 0
Draw.line([0, 0], [0, 16], { width: 3 });
Draw.circle([0, 20], 4);

// 阶段边界（t=10 s 时加速结束，固定世界坐标 x = 100 m）
Draw.line([100, 0], [100, 60], { width: 1, dash: true });

// 救护车：质心位置完全来自 state
Draw.box([amb.x, amb.y + 10], 40, 20);
Draw.circle([amb.x - 12, amb.y], 2);
Draw.circle([amb.x + 12, amb.y], 2);

// 鸣笛声向出发点传播（示意，随车移动）
Draw.arc([amb.x, amb.y + 12], 30, 100, 260);
Draw.arc([amb.x, amb.y + 12], 44, 100, 260);
Draw.line([amb.x - 22, amb.y + 22], [0, amb.y + 22], { width: 1, dash: true });

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(41, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "ambulance.x", label: "ambulance 水平位置", value: state.ambulance.x, unit: 'm' });
out.push({ key: "ambulance.y", label: "ambulance 竖直位置", value: state.ambulance.y, unit: 'm' });
out.push({ key: "ambulance.vx", label: "ambulance 水平速度", value: (b.ambulance.x - a.ambulance.x) / dt, unit: 'm/s' });
out.push({ key: "ambulance.vy", label: "ambulance 竖直速度", value: (b.ambulance.y - a.ambulance.y) / dt, unit: 'm/s' });
return out;
